TargetContent:
  "title": "Fittings: Den sikre form for retningsændring",
  "lead": "Hver retningsændring, hver forgrening er et kritisk punkt. K Aqua PP-R fittings omdanner disse punkter til systemets stærkeste led – takket være homogen molekylær sammensmeltning."
},
"intro": {
  "eyebrow": "Sømløs integration",
  "title": "Når to dele bliver til én.",
  "lead": "I modsætning til limede eller pressede rørforbindelser anvender vi termisk polyfusion. Fitting og rør opvarmes og smeltes sammen, så de danner én enkelt, uadskillelig struktur uden pakninger eller svage punkter."
},
"sticky": {
  "eyebrow": "Fitting Typer",
  "title": "Det komplette sortiment.",
  "lead": "Vores sortiment af fittings giver dig mulighed for at bygge enhver tænkelig geometri i rørnettet uden at gå på kompromis med gennemstrømning eller sikkerhed.",
  "items": [
    {
      "title": "Vinkler & Bøjninger",
      "desc": "45° og 90° vinkler til retningsændringer. Vores flow-optimerede design minimerer tryktabet i bøjningen markant sammenlignet med standard fittings."
    },
    {
      "title": "T-stykker & Forgreninger",
      "desc": "Lige og reducerede T-stykker til effektiv fordeling af væsker. Designet til at modstå de høje trykforskelle ved forgreninger."
    },
    {
      "title": "Muffer & Reduktioner",
      "desc": "Forbinder rør af samme eller forskellige diametre sikkert og permanent. Reduktioner er udformet konisk for at undgå kavitation."
    },
    {
      "title": "Endekapper & Propper",
      "desc": "Til sikker og tryktæt afslutning af rørledninger eller midlertidig forsegling af systemer under byggefasen."
    }
  ]
},
"bento": {
  "eyebrow": "Materialefordele",
  "title": "Perfektion i detaljen.",
  "lead": "En fitting er mere end et stykke plast. Det er resultatet af avanceret sprøjtestøbningsteknologi.",
  "items": [
    {
      "title": "Ingen O-ringe nødvendige",
      "desc": "Da røret og fittingen smelter sammen, er der ikke brug for gummipakninger, som med tiden kan mørne, lække eller blive en grobund for bakterier."
    },
    {
      "title": "Forstærkede vægge",
      "desc": "Vores fittings har øget vægtykkelse i kritiske områder (f.eks. i bøjningens yderradius) for at modstå erosion og høje trykstød."
    },
    {
      "title": "Glat inderside",
      "desc": "Sprøjtestøbningsprocessen garanterer en ekstremt glat indvendig overflade. Dette reducerer friktionstab til et minimum og forhindrer aflejringer (inkrustation)."
    },
    {
      "title": "UV-Beskyttelse (Valgfrit)",
      "desc": "Til udendørs installationer tilbyder vi sorte, UV-bestandige PP-R fittings, der modstår langvarig eksponering for sollys uden at miste mekanisk styrke."
    }
  ]
},
"timeline": {
  "title": "Sprøjtestøbningsprocessen",
  "desc": "Hvordan vi fremstiller vores fittings med præcision på mikrometerniveau.",
  "items": [
    {
      "year": "Trin 1",
      "title": "Granulat Forberedelse",
      "text": "Premium PP-R og PP-RCT granulat tørres og forvarmes til en præcis temperatur for at sikre en fuldstændig homogen smelte."
    },
    {
      "year": "Trin 2",
      "title": "Højtryksinjektion",
      "text": "Det smeltede plast injiceres i højpræcise stålforme ved tryk på op til 2000 bar. Herved udfyldes formen komplet, og luftlommer forhindres."
    },
    {
      "year": "Trin 3",

        "title": "Kontrolleret Afkøling",
        "text": "Formen afkøles gradvist. Dette forhindrer indre spændinger i fittingen og garanterer en fuldstændig formstabilitet uden krympning."
      },
      {
        "year": "Trin 4",
        "title": "Kvalitetssikring",
        "text": "Hver batch underkastes dimensionskontrol, varmeovnstest (for at tjekke for restspændinger) og tryktest inden frigivelse."
      }
    ]
  },
