"pipes": {
  "meta": {
    "title": "PP-R og PPRCT Rørsystemer",
    "desc": "Højtydende K Aqua plastrør af PP-R og PP-RCT med glasfiberforstærkning til drikkevand, varme og industriel væsketransport."
  },
  "hero": {
    "eyebrow": "Kernekomponenten",
    "title": "Rørsystemer: Livsnerven i din bygning",
    "lead": "K Aqua rør af PP-R og PP-RCT (Polypropylene Random Copolymer med modificeret krystalstruktur) sætter standarden for sikker, hygiejnisk og langtidsholdbar væsketransport under ekstreme forhold."
  },
  "intro": {
    "eyebrow": "Evolution i plast",
    "title": "Mere end bare et rør.",
    "lead": "Hvor metalrør korroderer, og traditionel plast giver efter for varme og tryk, leverer K Aqua rørsystemer. Vores flerlags fiberkompositrør minimerer termisk udvidelse og maksimerer den hydrauliske kapacitet."
  },
  "sticky": {
    "eyebrow": "Rørtyper",
    "title": "Det rigtige rør til enhver opgave.",
    "lead": "Vores sortiment er designet til at dække hele spektret af bygnings- og industriteknik - fra iskoldt drikkevand til kogende procesvand.",
    "items": [
      {
        "title": "PP-R Standard Rør",
        "desc": "Den pålidelige allrounder til kolde og varme brugsvandsinstallationer. Ekstremt robust, let at svejse og fås i trykklasserne SDR 11 og SDR 6."
      },
      {
        "title": "PP-RCT Fiber Rør (Faser)",
        "desc": "Det højtydende kompositrør med et mellemlag af glasfiber. Det reducerer den termiske længdeudvidelse med 75% og muliggør større rørafstande ved fastgørelse. Ideelt til stigrør og varmesystemer."

    },
    {
      "title": "PP-RCT Multilayer (Alu)",
      "desc": "Kombinerer fordelene ved plast og metal. Med et mellemlag af aluminium er røret 100% ilttæt, hvilket gør det til det perfekte valg til lukkede klimakredsløb og radiatorinstallationer."
    },
    {
      "title": "UV-Bestandige Rør (Lilla/Sort)",
      "desc": "Til udendørs brug eller identifikation af specifikke vandkredsløb (f.eks. genbrugsvand/lilla). Den specielle kappe beskytter mod UV-nedbrydning."
    }
  ]
},
"bento": {
  "eyebrow": "Materialeegenskaber",
  "title": "Hvorfor K Aqua Rør vinder.",
  "lead": "Sammenlignet med stål, kobber eller CPVC tilbyder Polypropylen klare mekaniske og hygiejniske fordele.",
  "items": [
    {
      "title": "PPRCT Teknologi",
      "desc": "Den forbedrede krystalstruktur (PP-RCT) tillader højere tryk ved høje temperaturer, hvilket betyder tyndere rørvægge, mindre vægt og op til 17% mere flow."
    },
    {
      "title": "Akustisk isolering",
      "desc": "Materialets elasticitet og densitet dæmper strømningsstøj markant og reducerer overførsel af vibrationer (vandhammerslag) gennem bygningen."
    },
    {
      "title": "Energi Effektivitet",
      "desc": "PP-R har en meget lav varmeledningsevne (0.24 W/mK). Det fungerer som en naturlig isolator, holder varmt vand varmt længere og forhindrer kondens på koldtvandsrør."
    },
    {
      "title": "Hygiejne & Sikkerhed",
      "desc": "Materialet er lys-uigennemtrængeligt (forhindrer algevækst), 100% korrosionsfrit, afgiver ikke tungmetaller og er godkendt til det reneste drikkevand."
    }
  ]
},
"timeline": {
  "title": "Ekstruderingsprocessen",
  "desc": "Sådan fremstiller vi trelagskompositrør (Fiber/Faser) i én kontinuerlig proces.",
  "items": [
    {
      "year": "Trin 1",
      "title": "Co-Ekstrudering",
      "text": "Tre separate ekstrudere opvarmer granulatet: PP-RCT til inder- og yderlaget, og en speciel blanding af PP-RCT og glasfiber til mellemlaget."
    },
    {
      "year": "Trin 2",
      "title": "Sammensmeltning i dyse",
      "text": "De tre smeltede materialestrømme føres sammen i et specialdesignet formhoved og forenes til ét homogent flerlagsrør."
    },
    {
      "year": "Trin 3",
      "title": "Vakuumkalibrering",
      "text": "Røret trækkes gennem et vandkølet vakuumkammer, som fryser den ydre diameter præcist fast for at garantere perfekte svejsetolerancer."
    },
    {
      "year": "Trin 4",
      "title": "Køling og Print",
      "text": "Efter yderligere kølebade påtrykkes produktionsdata, standarder og dimensioner med laser eller blæk, hvorefter røret skæres i standardlængder på 4 meter."
    }
  ]
},
